import urllib.request, json

def fetch_epss(cves):
    cve_str = ','.join(cves)
    url = f'https://api.first.org/data/v1/epss?cve={cve_str}'
    req = urllib.request.Request(url, headers={'User-Agent': 'Aegis-SOC-CTEM/2.0'})
    try:
        with urllib.request.urlopen(req, timeout=5) as resp:
            data = json.loads(resp.read().decode('utf-8'))
            mapping = {}
            for item in data.get('data', []):
                mapping[item['cve']] = {
                    'epss': float(item.get('epss', 0.0)),
                    'percentile': float(item.get('percentile', 0.0)),
                    'date': item.get('date', 'Unknown'),
                    'source': 'FIRST.org Live API v1.0'
                }
            return mapping
    except Exception as e:
        print('Error:', e)
        return {}

cves = ['CVE-2024-10491', 'CVE-2014-6393', 'CVE-2024-9266', 'CVE-2024-43796', 'CVE-2024-29041']
